typedef unsigned int u_int;

struct sceCdlFILE {
    unsigned int lsn;
    unsigned int size;
    char name[16];
    unsigned char date[8];
};

struct sceCdRMode {
    unsigned char trycount;
    unsigned char spindlctrl;
    unsigned char datapattern;
};

struct StrFile {
    int isOnCD;
    int size;
    sceCdlFILE fp;
    unsigned char *iopBuf;
    int fd;
};

extern int isStrFileInit;
int nvlPrintf(const char *format, ...);
static int strFileClose(StrFile *file);
extern "C" char *index(const char *string, int character);
extern "C" char *strncpy(char *destination, const char *source, unsigned int count);
extern "C" char *strcpy(char *destination, const char *source);
extern "C" int strcmp(const char *left, const char *right);
extern "C" unsigned int strlen(const char *string);
extern "C" int sprintf(char *buffer, const char *format, ...);
extern "C" int toupper(int character);
extern "C" int sceCdDiskReady(int mode);
extern "C" void *sceSifAllocIopHeap(int size);
extern "C" int sceCdStInit(unsigned int bufmax, unsigned int bankmax, unsigned int iop_buf);
extern "C" int sceCdSearchFile(sceCdlFILE *file, const char *name);
extern "C" int sceCdStStart(unsigned int lsn, sceCdRMode *mode);
extern "C" int sceOpen(const char *name, int flags);
extern "C" int sceLseek(int fd, int offset, int origin);
extern "C" int sceClose(int fd);

__asm__(".equ isStrFileInit, 0x0048AFF8");
__asm__(".equ nvlPrintf__FPCce, 0x0038AD50");
__asm__(".equ strFileClose__FP7StrFile, 0x003894B0");
__asm__(".equ sceCdDiskReady, 0x003BD720");
__asm__(".equ sceSifAllocIopHeap, 0x003DF5D0");
__asm__(".equ sceCdStInit, 0x003BDE00");
__asm__(".equ sceCdSearchFile, 0x003BCCB8");
__asm__(".equ sceCdStStart, 0x003BDE30");
__asm__(".equ sceOpen, 0x003DE978");
__asm__(".equ sceLseek, 0x003DED80");
__asm__(".equ sceClose, 0x003DEC00");

#define bound(value, alignment) (((value) + (alignment) - 1) & ~((alignment) - 1))

static int strFileOpen(StrFile* file, char* filename)
{
    int     ret;
    char    *body = 0, fn[256], devname[64], nullstr[] = "", cdendstr[] = ";1";

    body = index(filename, ':');
    if (body)
    {
        int dlen;

        dlen = body - filename;
        strncpy(devname, filename, dlen);
        devname[dlen] = 0;
        body += 1;
        if (!strcmp(devname, "cdrom0"))
        {
            int     len = strlen(body);
            char    *tail;

            file->isOnCD = 1;
            for (int i = 0; i < len; i++)
            {
                if (body[i] == '/')
                {
                    body[i] = '\\';
                }
                body[i] = toupper(body[i]);
            }
            tail = index(filename, ';') ? nullstr : cdendstr;
            sprintf(fn, "%s%s", body, tail);
        }
        else
        {
            file->isOnCD = 0;
            sprintf(fn, "%s:%s", devname, body);
        }
    }
    else
    {
        body = filename;
        strcpy(devname, "host0");
        file->isOnCD = 0;
        sprintf(fn, "%s:%s", devname, body);
    }
    nvlPrintf("file: %s\n", fn);
    if (file->isOnCD)
    {
        sceCdRMode mode;

        if (!isStrFileInit)
        {
            sceCdDiskReady(0);
            isStrFileInit = 1;
        }
        file->iopBuf = (unsigned char*)sceSifAllocIopHeap(((2048 * 80) + 16));
        sceCdStInit(80, 5, bound((u_int)file->iopBuf, 16));
        if (!sceCdSearchFile(&file->fp, fn))
        {
            nvlPrintf("Cannot open '%s'(sceCdSearchFile)\n", fn);
            strFileClose(file);
            return 0;
        }
        file->size = file->fp.size;
        mode.trycount = 0;
        mode.spindlctrl = 0;
        mode.datapattern = 0;
        sceCdStStart(file->fp.lsn, &mode);
    }
    else
    {
        file->fd = sceOpen(fn, 1);
        if (file->fd < 0)
        {
            nvlPrintf("Cannot open '%s'(sceOpen)\n", fn);
            return 0;
        }
        file->size = sceLseek(file->fd, 0, 2);
        if (file->size < 0)
        {
            nvlPrintf("sceLseek() fails (%s): %d\n", fn, file->size);
            sceClose(file->fd);
            return 0;
        }
        ret = sceLseek(file->fd, 0, 0);
        if (ret < 0)
        {
            nvlPrintf("sceLseek() fails (%s)\n", fn);
            sceClose(file->fd);
            return 0;
        }
    }
    return 1;
}

__asm__(".globl strFileOpen__FP7StrFilePc");
